begin;
create function public.get_platform_advertising_credit_page(p_company_id uuid,p_original_invoice_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.advertising_credit_page(p_company_id,p_original_invoice_id,true); $$;
revoke all on function public.get_platform_advertising_credit_page(uuid,uuid) from public,anon,service_role;
grant execute on function public.get_platform_advertising_credit_page(uuid,uuid) to authenticated;
create function public.list_advertising_credit_page(p_company_id uuid,p_original_invoice_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.advertising_credit_page(p_company_id,p_original_invoice_id,false); $$;
revoke all on function public.list_advertising_credit_page(uuid,uuid) from public,anon,service_role;
grant execute on function public.list_advertising_credit_page(uuid,uuid) to authenticated;
create function public.get_platform_advertising_credit_invoice(p_company_id uuid,p_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.get_advertising_credit_invoice(p_company_id,p_id,true); $$;
revoke all on function public.get_platform_advertising_credit_invoice(uuid,uuid) from public,anon,service_role;
grant execute on function public.get_platform_advertising_credit_invoice(uuid,uuid) to authenticated;
create function public.get_advertising_credit_invoice(p_company_id uuid,p_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.get_advertising_credit_invoice(p_company_id,p_id,false); $$;
revoke all on function public.get_advertising_credit_invoice(uuid,uuid) from public,anon,service_role;
grant execute on function public.get_advertising_credit_invoice(uuid,uuid) to authenticated;
create function public.configure_advertising_credit_series(p_company_id uuid,p_original_invoice_id uuid,p_expected_original_source_hash text,p_year integer,p_prefix text,p_first_number text,p_seller_registered_seat text,p_reason text,p_review_acknowledged boolean,p_request_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.configure_advertising_credit_series(p_company_id,p_original_invoice_id,p_expected_original_source_hash,p_year,p_prefix,p_first_number,p_seller_registered_seat,p_reason,p_review_acknowledged,p_request_id); $$;
revoke all on function public.configure_advertising_credit_series(uuid,uuid,text,integer,text,text,text,text,boolean,uuid) from public,anon,service_role;
grant execute on function public.configure_advertising_credit_series(uuid,uuid,text,integer,text,text,text,text,boolean,uuid) to authenticated;
create function public.issue_advertising_credit_invoice(p_company_id uuid,p_original_invoice_id uuid,p_expected_original_source_hash text,p_expected_series_id uuid,p_expected_series_review_token text,p_expected_review_token text,p_reason text,p_review_acknowledged boolean,p_request_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select private.issue_advertising_credit_invoice(p_company_id,p_original_invoice_id,p_expected_original_source_hash,p_expected_series_id,p_expected_series_review_token,p_expected_review_token,p_reason,p_review_acknowledged,p_request_id); $$;
revoke all on function public.issue_advertising_credit_invoice(uuid,uuid,text,uuid,text,text,text,boolean,uuid) from public,anon,service_role;
grant execute on function public.issue_advertising_credit_invoice(uuid,uuid,text,uuid,text,text,text,boolean,uuid) to authenticated;
commit;
